// План specs/admin-access.md, 3.1 (кейс AA-06). Пользователь «בדיקה», иврит. Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { DASHBOARD_URL, expectNoAdminPanel, sectionTab } from './access-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Admin Panel — доступ обычного пользователя (#12126fac)', () => {
  test('Non-admin opening /adminpanel is redirected to the dashboard without "אין גישה" (HE) #12126fac @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'he');

    await page.goto('/adminpanel');
    await expect(page).toHaveURL(DASHBOARD_URL);
    await expect(page.getByText('אין גישה')).toHaveCount(0);
    await expect(sectionTab(page, 'חבילות')).toHaveCount(0);
    await expectNoAdminPanel(page);
  });
});
